fn bin_search(a: &[i32], k: i32) -> bool {
    let mut left = 0;
    let mut right = a.len() as i32 - 1;

    while left <= right {
        let mid = left + (right - left) / 2;
        if a[mid as usize] == k {
            return true;
        } else if a[mid as usize] < k {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    false
}